    aggNoteBasis: "Jeder Erlass in Kraft zählt einmal: in seinem Block (Stockwerk × Sachgebiet der SR, bei kantonalem Recht × Kanton) und in einem Fluss von der Grundlage, an der er im Baum hängt. Breite = Zahl der Erlasse, Massstab je für Bund und Kantone; oben zeigt ein Fluss den Anteil an allem, was auf dem Block ruht. Ohne Herkunft im Baum (kurze Stummel oben am Block): nur Bundesrecht genannt (blau); eine kantonale Grundlage genannt, aber nicht bestimmbar oder nicht übergeordnet (ocker); keine Grundlage genannt (grau); kein Ingress veröffentlicht (schraffiert).",
    aggNoteLaw: (n) => `Bestimmungen von Bundeserlassen, die einen Erlass eines anderen Blocks nennen (Fussnoten mit SR-Nummer; nur Bundesrecht). Die ${n} stärksten Paare; Zeigen auf einen Block zeigt alle seine.`,
    aggNoteCourt: (n) => `Entscheide, die Erlasse beider Blöcke zitieren, geordnet nach n·ln(Lift) (Lift = beobachtet / erwartet; nur Lift ≥ 1,5, damit allgegenwärtige Verfahrensgesetze nicht alles überdecken). Die ${n} stärksten Paare.`,
    aggTip: "Klicken: Erlasse und Verbindungen", aggFlow: (n, d, s) => `${n} Erlasse in ${d} stützen sich auf ${s}`,
    aggOnlyFed: "nur Bundesrecht genannt", aggNone: "keine Grundlage genannt", aggUnres: "Grundlage genannt, nicht bestimmbar", aggLower: "nur nicht übergeordnete Erlasse genannt", aggNoIng: "kein Ingress veröffentlicht", aggNoParent: "Ohne Grundlage im Baum", 
    viewMat: "Matrix", matScope: "Ausschnitt", matAll: "Alles", matLowUnit: "Grundlagen auf einer tieferen Ebene", matLowNote: "Ein Erlass nennt im Ingress einen Erlass einer tieferen Ebene. Jeder Fall ist von Hand gelesen (Stand 27.10.2026) und einer von sechs Gruppen zugeordnet; nur die erste kehrt die Delegation wirklich um.", matLow_claim: "Tiefere Grundlage ausdrücklich genannt", matLowN_claim: "Der Erlass stützt sich ausdrücklich auf einen Erlass einer tieferen Behörde: Die Delegationskette läuft nach oben. Material für Phase 2.", matLow_floor: "Ebene des genannten Erlasses unbestimmt", matLowN_floor: "Die Sammlung nennt für den genannten Erlass keine Behörde, und der Titel sagt nichts: Ebene 7 ist ein Ersatzwert, kein Befund. Von Hand gelesen kann die Umkehr entfallen.", matLow_party: "Vereinbarung nennt die Norm einer Partei", matLowN_party: "Vereinbarungen stehen unabhängig von der abschliessenden Behörde auf Ebene 5 (Kanton mit Gemeinden: 6); die Norm, die eine Regierung oder Gemeinde zum Abschluss ermächtigt, liegt tiefer. Keine Umkehr der Geltung.", matLow_context: "Ingress nennt einen tieferen Erlass als Kontext", matLowN_context: "Die Liste der genannten Erlasse führt neben dem Gesetz dessen Vollziehungsverordnung oder einen Erlass, den der neue voraussetzt – keine Delegation.", matLow_successor: "Nummer trägt heute einen späteren Erlass", matLowN_successor: "Der Ingress nennt einen früheren Erlass mit Datum; die Nummer der Fussnote trägt heute dessen Nachfolger, erlassen von einer tieferen Behörde.", matLow_approval: "Genehmigung nennt den genehmigten Vertrag", matLowN_approval: "Ein Genehmigungsbeschluss nennt den Vertrag, den er genehmigt; dieser steht nur nach seinem Titel tiefer.", matLow_open: "Noch nicht gelesen", matLowN_open: "Seit der Durchsicht hinzugekommen; noch keiner Gruppe zugeordnet.", matTop: "Die stärksten Zellen", matWhere: "Wo die genannten Grundlagen liegen", matFed: "Bund", matCant: "Kantone", matOwn: "Eigener Kanton",
    matF1: "Bundesversammlung", matF2: "Bundesrat, Gerichte", matF3: "Departemente, Ämter", matK4: "Verfassung", matK5: "Parlament, Volk", matK6: "Regierung, Gerichte", matK7: "Direktionen, Ämter",
    matSameOrder: "Bund – Spalten in der Reihenfolge der Zeilen",
    matNoteBasis: (n, h, s, l) => `Zeile: der Block, dessen Erlasse sich stützen; Spalte: der Block, auf den sie sich stützen. Zelle = Erlasse der Zeile, die im Ingress eine Grundlage in der Spalte nennen – jede genannte Grundlage, nicht nur der Platz im Baum. Unter der Diagonale liegt die Grundlage auf einer höheren Ebene, in den grauen Feldern auf derselben, darüber auf einer tieferen. Von ${n} genannten Grundlagen: ${h} höher, ${s} gleich, ${l} tiefer.`,
    matNoteLaw: "Zelle = Bestimmungen der Bundeserlasse der Zeile, die einen Erlass der Spalte mit SR-Nummer oder Link nennen (geltender deutscher Text). Die kantonalen Texte sind nicht gelesen: ihre Zeilen bleiben leer.",
    matNoteCourt: (m) => `Zelle = wie viel häufiger Entscheide Erlasse beider Blöcke zusammen zitieren, als bei unabhängiger Zitierung zu erwarten (Lift); gefärbt ab ${m} gemeinsamen Entscheiden und Lift über 1. Die Diagonale bleibt leer: dafür müssten zwei Erlasse desselben Blocks in einem Entscheid gezählt werden.`,
    matScaleBasis: "Erlasse", matScaleLaw: "Bestimmungen", matScaleCourt: "Lift", matSame: "dieselbe Ebene",
    matBasisTip: (n, np) => `${n} Erlasse nennen hier eine Grundlage; für ${np} ist es ihr Platz im Baum`, matLawTip: (n, p) => `${n} Bestimmungen nennen hier einen Erlass (${p} Paare von Erlassen)`,
    matLawCant: "Kantonale Texte nicht gelesen", matLawNote: "Bestimmungen eines Bundeserlasses, die einen anderen mit SR-Nummer oder Link nennen. Die Fussnote steht meist nur bei der ersten Erwähnung: eine Untergrenze.",
    matCourtTip: (n, l) => `${n} Entscheide zitieren Erlasse beider Blöcke · ${l}-mal so oft wie erwartet`, matCourtFew: (n, l) => `${n} Entscheide zitieren beide (Lift ${l}) – nicht gefärbt`,
    matCourtDiag: "Diagonale: nicht gezählt", matNone: "Keine Verbindung", matHigher: "Grundlage auf einer höheren Ebene", matSameF: "Grundlage auf derselben Ebene", matLower: "Grundlage auf einer tieferen Ebene",
    matClick: "Klicken: die Erlasse dahinter", matPrim: "Platz im Baum", matPanelBasis: "Erlasse und was sie hier nennen", matPanelLaw: "Erlass-Paare, nach Zahl der Bestimmungen", matPanelCourt: "Am häufigsten zusammen zitiert",
    matCourtNote: (n, l) => `${n} Entscheide zitieren mindestens einen Erlass jedes Blocks; ${l}-mal so oft, wie bei unabhängiger Zitierung zu erwarten wäre.`,
    matCourtPairs: "Paare des ausgedünnten Kozitationsnetzes (mindestens 20 gemeinsame Entscheide, Lift ≥ 2, je Erlass die acht stärksten): einzelne Erlasse, nicht alle Entscheide.",
    matAria: "Matrix: welche Blöcke sich auf welche stützen. Pfeiltasten wählen eine Zelle, Eingabe öffnet sie.",
    aggStubShare: (n, N, p, row, pAll, lo, loP, hi, hiP) => `${n} von ${N} Erlassen dieses Blocks (${p}). Auf der Ebene «${row}» aller Kantone: ${pAll}; am wenigsten ${lo} (${loP}), am meisten ${hi} (${hiP}) – gezählt sind Kantone mit mindestens 20 Erlassen auf dieser Ebene.`, basisFedAnyShort: "Bundesrecht allgemein, ohne bestimmten Erlass",
    aggLawTip: (n, p) => `${n} Bestimmungen in ${p} Erlasspaaren`, aggCourtTip: (n, l) => `${n} Entscheide zitieren beide · ${l}-mal so oft wie erwartet`,
