    webUp: "Stützt sich auf", webDown: "Darauf stützen sich", webDownKey: "die meistzitierten zuerst", webDownApex: "Artikel, auf die sich die meisten Erlasse stützen",
    webLaw: "Gesetzgebung", webLawKey: (a) => `→ ${a} nennt es, ← es nennt ${a}; Zahl der Bestimmungen`,
    webCourt: "Rechtsprechung", webCourtKey: "Entscheide, die beide zitieren", webDec: "Meistzitierte Entscheide",
    webMore: (n) => `+ ${n} weitere`, webOf: (a, b) => `${a} von ${b}`, webActs: (n) => `${n} Erlasse`, webUnk: (n) => `+ ${n} nicht bestimmbar`,
    st_overview: (f, k, d) => `${f} Erlasse des Bundes (ohne Staatsverträge) und ${k} der Kantone, jeder ein Punkt. Jede Linie führt von einem Erlass zur Bestimmung, auf die er sich stützt – bis hinauf zur Bundesverfassung. ${d} Gerichtsentscheide beziehen sich auf mindestens einen Erlass des Bundes (samt Staatsverträgen) oder der Kantone, geltend oder früher.`,
    st_apex: (a, b, r) => `${a} Artikel. Auf ${b} davon stützen sich Erlasse ausdrücklich in ihrem Ingress, zusammen ${r} Nennungen. Der Bund hat nur die Zuständigkeiten, die ihm die Verfassung zuweist (Art. 3 und 42 BV).`,
    st_floor1: (n, bv, none) => `${n} Erlasse der Bundesversammlung: Bundesgesetze, Bundesbeschlüsse und ihre Verordnungen. ${bv} hängen direkt an einem Verfassungsartikel; ${none} nennen im Ingress keine Grundlage.`,
    st_floor2: (n, l1, bv) => `${n} Erlasse, fast alle Verordnungen. ${l1} stützen sich auf einen Erlass der Bundesversammlung, ${bv} direkt auf die Verfassung.`,
    st_floor3: (n, l2, l1) => `${n} Erlasse von Departementen, Ämtern und weiteren Behörden, meist Verordnungen. ${l2} stützen sich auf einen Erlass des Bundesrats oder eines Bundesgerichts, ${l1} direkt auf einen Erlass der Bundesversammlung.`,
    st_cantons: (n, r) => `Jeder Kanton gibt sich eine Verfassung (Art. 51 BV). Darunter ${n} kantonale Erlasse in Kraft – ${r}-mal so viele wie Erlasse des Bundes ohne Staatsverträge. Sie liegen tiefer, weil Bundesrecht entgegenstehendem kantonalem Recht vorgeht (Art. 49 BV).`,
    st_courts: (d) => `Die Grösse einer Kugel zeigt, wie viele Entscheide sich auf den Erlass beziehen (${d} Entscheide nennen mindestens einen Erlass). Am meisten:`,
    st_courtsAct: (a, n) => `${a}: ${n} Entscheide beziehen sich darauf. Unter dem Erlass hängen die meistzitierten: je grösser, desto öfter zitieren andere Entscheide sie.`,
    fBy: (w) => `erlassen von: ${w}`, fFloor: (w) => `Stockwerk: ${w}`, fDec: (n) => `${n} Entscheide beziehen sich darauf`, fRest: (n) => `${n} Erlasse stützen sich darauf`,
    op1: (n) => `1 Bundesverfassung · ${n} Artikel`, op2: (n) => `${n} Erlasse des Bundes`, op4: (n) => `${n} Erlasse der Kantone`, op5: (n) => `${n} Gerichtsentscheide`,
    hudFed: (n) => `${n} Bundeserlasse`, hudKant: (n) => `${n} kantonale`, hudYear: (y) => `erlassen bis ${y}`, hudDec: (n) => `${n} Entscheide`, alsoCited: (a, n, more) => `Zitiert als ${a} (${n}) und als ${more}; die Zahl oben zählt jeden Entscheid einmal.`, ingressK: "Ingress (Text der kantonalen Sammlung)", finalProv: "SchlB", kNoIngress: "Die kantonale Sammlung veröffentlicht für diesen Erlass keinen Ingress.", acts: "Erlasse", cantonalColl: (n) => `Gesetzessammlung ${n}`,
    introTree: "Oben die Bundesverfassung, darunter jeder geltende Bundeserlass an der Bestimmung, auf die sich sein Ingress stützt – auf der Ebene der Behörde, die ihn erlassen hat: Bundesversammlung, Bundesrat und Gerichte, Departemente und Ämter. Darunter die 26 Kantonsverfassungen (Art. 51 BV) und das kantonale Recht – unter allem Bundesrecht, weil es diesem weicht (Art. 49 BV). Bögen zeigen, was Gerichte gemeinsam zitieren und welcher Text auf welchen verweist. Klicken, um einzutauchen.",
    refersTo: "Verweist im Text auf", referredBy: "Wird im Text verwiesen von", refsN: (n) => (n === "1" ? "1 Bestimmung" : `${n} Bestimmungen`),
    lawOnly: "Nur im Gesetzestext verbunden, Gerichte zitieren sie kaum gemeinsam",
    practiceOnly: "Nur in der Praxis verbunden: kein Textverweis, aber oft gemeinsam zitiert",
    intro: "Jede Kugel ist ein Erlass der Systematischen Rechtssammlung, so gross wie die Zahl der Entscheide, die auf ihn verweisen. Bahnen zeigen, wie Erlasse zusammenhängen: über der Ebene die Gerichtspraxis, darunter der Gesetzestext. Klicken, um einzutauchen.",
    introOk: "Erkunden", time: "Zeit", play: "Abspielen", pause: "Anhalten", year: "Jahr",
    view3d: "Neigen", viewTop: "Von oben", viewSide: "Seitlich", themeDark: "Dunkler Hintergrund", themeLight: "Heller Hintergrund", treeAll: "Alle Verbindungen zeigen (sonst nur die des gewählten Erlasses)", focusAll: "Alle Verbindungen", inYear: (y) => `bis ${y}`,
